// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.common/** * NOUS — Result type. * * Not kotlin.Result because we need metadata (timing, dispatcher used, * correlation ID, retryable flag, partial-success support). * * Every Brain layer, every skill, every feature returns [Result] instead of * throwing. Failures are first-class values, not exceptions. * * Sealed hierarchy with three variants: *   - [Success] — operation completed, here's the data *   - [Failure] — operation failed, here's the typed error *   - [Partial] — operation succeeded with warnings (e.g., LLM timed out, fell back) * * @param T the success value type */sealed interface Result<out T> {    /** Correlation ID for tracing this request across the system. */    val correlationId: CorrelationId    /** Wall-clock duration of the operation, in nanoseconds. */    val durationNanos: Long    /**     * Operation succeeded.     *     * @param data the success value     * @param warnings optional warnings (empty if perfectly clean)     */    data class Success<T>(        val data: T,        override val correlationId: CorrelationId,        override val durationNanos: Long,        val warnings: List<String> = emptyList(),        val metadata: Map<String, String> = emptyMap(),    ) : Result<T>    /**     * Operation failed.     *     * @param error typed error (see [AppError])     */    data class Failure(        val error: AppError,        override val correlationId: CorrelationId,        override val durationNanos: Long,    ) : Result<Nothing>    /**     * Operation succeeded, but with caveats.     *     * Example: LLM call timed out, fell back to cached answer. We have a     * usable [data] but the [warnings] should be surfaced to the user or     * logged.     */    data class Partial<T>(        val data: T,        val warnings: List<String>,        override val correlationId: CorrelationId,        override val durationNanos: Long,    ) : Result<T>}// ─── Convenience helpers ────────────────────────────────────────────────────/** True if this result is a [Result.Success]. */val <T> Result<T>.isSuccess: Boolean get() = this is Result.Success/** True if this result is a [Result.Failure]. */val <T> Result<T>.isFailure: Boolean get() = this is Result.Failure/** Get the success value, or null if this is a Failure. */val <T> Result<T>.getOrNull: T?    get() = when (this) {        is Result.Success -> data        is Result.Partial -> data        is Result.Failure -> null    }/** Get the error, or null if this is a Success. */val <T> Result<T>.errorOrNull: AppError?    get() = (this as? Result.Failure)?.error/** Map the success value via [transform]. Failures pass through unchanged. */inline fun <T, R> Result<T>.map(transform: (T) -> R): Result<R> = when (this) {    is Result.Success -> Result.Success(        data = transform(data),        correlationId = correlationId,        durationNanos = durationNanos,        warnings = warnings,        metadata = metadata,    )    is Result.Partial -> Result.Partial(        data = transform(data),        warnings = warnings,        correlationId = correlationId,        durationNanos = durationNanos,    )    is Result.Failure -> this}/** Flat-map the success value via [transform]. Failures pass through unchanged. */inline fun <T, R> Result<T>.flatMap(transform: (T) -> Result<R>): Result<R> = when (this) {    is Result.Success -> transform(data)    is Result.Partial -> when (val next = transform(data)) {        is Result.Success -> Result.Partial(            data = next.data,            warnings = warnings + next.warnings,            correlationId = correlationId,            durationNanos = durationNanos,        )        is Result.Partial -> Result.Partial(            data = next.data,            warnings = warnings + next.warnings,            correlationId = correlationId,            durationNanos = durationNanos,        )        is Result.Failure -> next    }    is Result.Failure -> this}/** Recover from a failure by providing a fallback value. */inline fun <T> Result<T>.getOrDefault(default: T): T = when (this) {    is Result.Success -> data    is Result.Partial -> data    is Result.Failure -> default}/** Run [action] on success, return the original result for chaining. */inline fun <T> Result<T>.onSuccess(action: (T) -> Unit): Result<T> {    if (this is Result.Success) action(data)    if (this is Result.Partial) action(data)    return this}/** Run [action] on failure, return the original result for chaining. */inline fun <T> Result<T>.onFailure(action: (AppError) -> Unit): Result<T> {    if (this is Result.Failure) action(error)    return this}// ─── Constructors (timed) ───────────────────────────────────────────────────/** * Wrap a synchronous block in a [Result.Success] or [Result.Failure]. * * Captures wall-clock duration. Maps thrown exceptions to [AppError.Unknown]. * Use [withCorrelationId] when you need to chain results with the same ID. */inline fun <T> result(block: (CorrelationId) -> T): Result<T> {    val correlationId = CorrelationId.generate()    val startNanos = System.nanoTime()    return try {        Result.Success(            data = block(correlationId),            correlationId = correlationId,            durationNanos = System.nanoTime() - startNanos,        )    } catch (throwable: Throwable) {        Result.Failure(            error = AppError.from(throwable, correlationId),            correlationId = correlationId,            durationNanos = System.nanoTime() - startNanos,        )    }}/** * Wrap a suspending block in a [Result.Success] or [Result.Failure]. * * Use this for any suspending function that returns a value but might fail. */suspend inline fun <T> resultSuspend(    correlationId: CorrelationId = CorrelationId.generate(),    crossinline block: suspend (CorrelationId) -> T,): Result<T> {    val startNanos = System.nanoTime()    return try {        Result.Success(            data = block(correlationId),            correlationId = correlationId,            durationNanos = System.nanoTime() - startNanos,        )    } catch (throwable: Throwable) {        Result.Failure(            error = AppError.from(throwable, correlationId),            correlationId = correlationId,            durationNanos = System.nanoTime() - startNanos,        )    }}